metrics.workdir_dsl:
workspace "Hospital Appointment System" "A minimal C4 model of a hospital appointment system." {
    model {
        patient = person "Patient" "A patient who books and manages hospital appointments."
        appointmentSystem = softwareSystem "Appointment System" "Allows patients to book and manage hospital appointments." {
            bookingWebApp = container "Booking Web App" "A web application for booking appointments." "ASP.NET Core MVC"
            schedulingService = container "Scheduling Service" "Manages appointment scheduling and availability." "Java"
        }
        patient -> bookingWebApp "Books appointments" "HTTPS"
        bookingWebApp -> schedulingService "Reserves time slots" "gRPC"
    }
    views {
        systemContext appointmentSystem "SystemContext" {
            include *
            autoLayout
        }
    }
}
